    {
      "id": "c:5499409957",
      "kind": "correctness",
      "harm": "EvalScript triggers an assertion failure when tracing is enabled if called with a null serror pointer (e.g. in CheckSignetBlockSolution)",
      "quote": "The tracing code assumes serror is non-null whenever a callback is registered, but EvalScript permits nullptr... This triggers the assertion assert(!m_callback || error);",
      "blocking": true,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    },
    {
      "id": "c:5499715130",
      "kind": "correctness",
      "harm": "oversized scripts are rejected before ScriptTraceScope is instantiated, preventing BEGIN and END trace frames from being emitted",
      "quote": "EvalScript rejects oversized scripts before constructing ScriptTraceScope, so a registered callback receives neither BEGIN nor END.",
      "blocking": false,
      "status": "open",
      "author_replies": [],
      "fix_pushed": false,
      "settled_by_id": "",
      "settled_by_quote": ""
    },
    {
      "id": "rc:3893679920",
      "kind": "correctness",
      "harm": "test suite fails when compiled with ENABLE_SCRIPT_TRACE=ON due to callback pushing into destroyed vector in subsequent tests",
      "quote": "Add ScriptTraceUnsetCallback() to avoid the next test case push into a destroyed vector. Test suite currently does not pass with the feature flag.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:5480776417"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5480776417",
      "settled_by_quote": "unsetting the callback after the trace tests are complete."
    },
    {
      "id": "rc:3675592714",
      "kind": "safety",
      "harm": "BOOST_CHECK_EQUAL on vector size allows test execution to continue and access out-of-bounds indices, causing undefined behavior",
      "quote": "BOOST_CHECK_EQUAL(states.size(), 11) is non-fatal, but the test checks states[0] through states[10] after this. So if the size check fails, the test still continues and may access out-of-bound items, resulting in an undefined behavior",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "c:5457530691"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5457530691",
      "settled_by_quote": "made the boost size check a hard requirement."
    },
    {
      "id": "rc:3758299224",
      "kind": "correctness",
      "harm": "null error pointer causes successful evaluation to report SCRIPT_ERR_UNKNOWN_ERROR in trace end frames",
      "quote": "a null m_error makes a successful eval report SCRIPT_ERR_UNKNOWN_ERROR. The kernel path always passes &error, but in case any non-kernel callers want to use the tracer, would it make sense to assert it in the ctor?",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
